<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Game of Life</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh; display: grid; place-items: center;
    color: #eafff6; font-family: system-ui, sans-serif;
    background: radial-gradient(circle at 50% 20%, #17365a, #080c1a 62%);
  }
  main { text-align: center; padding: 24px; }
  h1 { margin: 0 0 6px; font-size: clamp(2rem, 5vw, 3.2rem); letter-spacing: .06em; }
  p { color: #9cb8d5; margin: 0 0 18px; }
  #life {
    width: min(600px, calc(100vw - 32px));
    height: min(600px, calc(100vw - 32px));
    min-width: 400px; min-height: 400px;
    display: block; border: 3px solid #71f6c3; border-radius: 16px;
    background: #071322; box-shadow: 0 0 30px #37d9a866, inset 0 0 30px #1b8cad44;
    cursor: crosshair; touch-action: none;
  }
  .controls { display: flex; justify-content: center; flex-wrap: wrap; gap: 10px; margin-top: 18px; }
  button {
    border: 0; border-radius: 999px; padding: 10px 17px; color: #071322;
    background: #8af8ce; font: 700 1rem system-ui, sans-serif; cursor: pointer;
    box-shadow: 0 4px 0 #34aa82; transition: transform .12s, background .12s;
  }
  button:hover { background: #d1ff70; transform: translateY(-2px); }
  button:active { transform: translateY(3px); box-shadow: 0 1px 0 #34aa82; }
  #play.running { background: #ffd36e; box-shadow: 0 4px 0 #c58a32; }
  @media (max-width: 430px) { #life { min-width: 0; min-height: 0; } }
</style>
</head>
<body>
<main>
  <h1>✨ Life Lab ✨</h1>
  <p>Click or drag to paint little living cells.</p>
  <canvas id="life" width="600" height="600" aria-label="Conway's Game of Life grid"></canvas>
  <div class="controls">
    <button id="step">Step ➜</button>
    <button id="play">▶ Play</button>
    <button id="random">🎲 Random</button>
    <button id="clear">✦ Clear</button>
  </div>
</main>
<script>
(() => {
  const canvas = document.getElementById("life");
  const ctx = canvas.getContext("2d");
  const w = 60, h = 60;
  let cells = new Uint8Array(w * h);
  let running = false, timer = null, painting = false, paintValue = 1;

  const index = (x, y) => y * w + x;
  const get = (x, y) => (x >= 0 && x < w && y >= 0 && y < h) ? cells[index(x, y)] : 0;

  function draw() {
    const cw = canvas.width / w, ch = canvas.height / h;
    ctx.fillStyle = "#071322";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = "#1d4660";
    ctx.lineWidth = 1;
    for (let x = 0; x <= w; x++) {
      ctx.beginPath(); ctx.moveTo(x * cw, 0); ctx.lineTo(x * cw, canvas.height); ctx.stroke();
    }
    for (let y = 0; y <= h; y++) {
      ctx.beginPath(); ctx.moveTo(0, y * ch); ctx.lineTo(canvas.width, y * ch); ctx.stroke();
    }
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
      if (!get(x, y)) continue;
      const px = x * cw, py = y * ch;
      ctx.fillStyle = "#8af8ce";
      ctx.shadowColor = "#5affc4"; ctx.shadowBlur = 9;
      ctx.fillRect(px + 1.5, py + 1.5, cw - 3, ch - 3);
      ctx.shadowBlur = 0;
    }
  }

  function step() {
    const next = new Uint8Array(w * h);
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
      let n = 0;
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (dx || dy) n += get(x + dx, y + dy);
      }
      const alive = get(x, y);
      next[index(x, y)] = (n === 3 || (alive && n === 2)) ? 1 : 0;
    }
    cells = next;
    draw();
  }

  function set(x, y, v) {
    if (x >= 0 && x < w && y >= 0 && y < h) cells[index(x, y)] = v ? 1 : 0;
  }
  function clear() { cells.fill(0); draw(); }

  function randomize() {
    for (let i = 0; i < cells.length; i++) cells[i] = Math.random() < 0.28 ? 1 : 0;
    draw();
  }

  function paint(event) {
    const r = canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - r.left) * w / r.width);
    const y = Math.floor((event.clientY - r.top) * h / r.height);
    if (x >= 0 && x < w && y >= 0 && y < h) { set(x, y, paintValue); draw(); }
  }

  canvas.addEventListener("pointerdown", e => {
    painting = true; canvas.setPointerCapture(e.pointerId);
    const r = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - r.left) * w / r.width), y = Math.floor((e.clientY - r.top) * h / r.height);
    paintValue = get(x, y) ? 0 : 1; paint(e);
  });
  canvas.addEventListener("pointermove", e => { if (painting) paint(e); });
  canvas.addEventListener("pointerup", () => painting = false);
  canvas.addEventListener("pointercancel", () => painting = false);

  document.getElementById("step").onclick = step;
  document.getElementById("random").onclick = randomize;
  document.getElementById("clear").onclick = clear;
  document.getElementById("play").onclick = function () {
    running = !running;
    this.classList.toggle("running", running);
    this.textContent = running ? "❚❚ Pause" : "▶ Play";
    if (running) timer = setInterval(step, 120);
    else clearInterval(timer);
  };

  window.life = { w, h, get, set, step, clear };
  draw();
})();
</script>
</body>
</html>
